    lpWorkflowsHeading: "Everything the office needs from the workday, without making the team dig for it.",
    lpWorkflowsIntro: "OpsFloa is designed around the daily loop: people start work, activity is captured, exceptions rise to the surface, and the back office closes the day with fewer loose ends.",
    lpWorkflowPeopleLabel: "People",
    lpWorkflowPeopleTitle: "Start the day knowing who is working and what needs attention.",
