    lpWorkflowBackOfficeTitle: "Turn daily activity into approvals, reports, and cleaner payroll.",
    lpWorkflowBackOfficeItem1: "Overtime and pay-period controls",
    lpWorkflowBackOfficeItem2: "Reports for managers and clients",
    lpWorkflowBackOfficeItem3: "QuickBooks Online sync add-on",
    lpOperatorKicker: "Mobile-first, office-ready",
    lpOperatorHeading: "Built for the gap between doing the work and proving what happened.",
    lpOperatorCopy: "Team members get a simple daily path. Admins get approvals, reports, inventory movement, customer history, and exceptions. The system keeps the record so no one has to reconstruct the week from messages, memory, and scattered files.",
    lpOperatorLink: "Create your free account",
    lpWhyKicker: "Why OpsFloa",
    lpWhyHeading: "Use one flexible system instead of forcing the team through five disconnected tools.",
    lpWhyIntro: "Most teams do not need more software noise. They need the important actions up front, the deeper controls nearby, and a reliable record of the day when payroll, customers, managers, or inventory questions come up.",
    lpDiffSimpleLabel: "Simple for the team",
    lpDiffSimpleTitle: "The daily screen can stay small, even when the system is powerful.",
    lpDiffSimpleItem1: "Show only the tools each role needs",
    lpDiffSimpleItem2: "Keep specialist workflows tucked away",
    lpDiffSimpleItem3: "Use labels that match the company language",
    lpDiffMoreLabel: "More than time tracking",
    lpDiffMoreTitle: "Time, work records, inventory, and approvals live together.",
    lpDiffMoreItem1: "Fewer disconnected spreadsheets and side chats",
    lpDiffMoreItem2: "Cleaner context for payroll and reporting",
    lpDiffMoreItem3: "One place to find what happened",
    lpDiffMovementLabel: "Built for movement",
    lpDiffMovementTitle: "It works for teams moving between desks, sites, shops, and customers.",
    lpDiffMovementItem1: "Mobile browser access with no app-store rollout",
    lpDiffMovementItem2: "Offline queue for spotty signal",
    lpDiffMovementItem3: "Admin controls when the work gets complex",
    lpPricingKicker: "Simple pricing",
    lpPricingHeading: "Start small. Add the operational depth only when the team needs it.",
    lpPlanBadge: "Most useful",
    lpPerMonth: "/mo",
    lpPlanFreeName: "Free",
    lpPlanFreeDetail: "Up to 3 team members, time clock, scheduling, and recent history.",
    lpPlanStarterName: "Starter",
    lpPlanStarterDetail: "Up to 10 team members, geofencing, exports, mileage, and pay-period controls.",
    lpPlanBusinessName: "Business",
    lpPlanBusinessDetail: "Reports, work tracking, customers, checklists, analytics, and 15 team members included.",
    lpFaqKicker: "Questions",
    lpFaqHeading: "The basics, without the brochure fog.",
    lpFaq1Q: "Does the team need an app store download?",
    lpFaq1A: "No. OpsFloa runs in the mobile browser and can be installed to the home screen as a PWA.",
    lpFaq2Q: "Does it work in bad signal?",
    lpFaq2A: "Yes. Clock and work submissions can queue locally and sync when the connection returns.",
    lpFaq3Q: "Can different teams see different tools?",
    lpFaq3A: "Yes. OpsFloa is built around roles, modules, and company labels so the app can stay simple day to day.",
    lpFaq4Q: "Can it handle payroll details?",
    lpFaq4A: "Yes. It supports approvals, overtime, prevailing wage workflows, pay-period locks, reports, and QuickBooks sync as an add-on.",
    lpFinalHeading: "Give the team a simple way to report work. Give the office a clean way to close the day.",
